def compact_booking(booking: Mapping[str, Any]) -> dict[str, Any]:
    """Return the identifying part of a booking, without large nested payloads."""
    compact: dict[str, Any] = {}
    for field in _COMPACT_FIELDS:
        if field in booking:
            compact[field] = booking[field]
    return compact


def _read_document(controller: Any, leveldb_path: str, timeout: int) -> Any:
    if controller is not None and hasattr(controller, "run_python_script"):
        script = LOCAL_STORAGE_SOURCE + "\nprint(json.dumps(read_state(%s, %s), ensure_ascii=False))\n" % (
            json.dumps(leveldb_path),
            json.dumps(STATE_KEY),
        )
        try:
            raw = controller.run_python_script(script, timeout=timeout)
        except Exception as exc:  # noqa: BLE001 - unreadable state is reported below
            raise RuntimeError(f"OPENTRIP_LOCAL_STATE_NOT_FOUND: {exc}") from exc
        payload = str(raw.get("stdout") or raw.get("output") or "").strip()
        if not payload:
            raise RuntimeError("OPENTRIP_LOCAL_STATE_NOT_FOUND: empty reader output")
        try:
            return json.loads(payload)
        except ValueError as exc:
            raise RuntimeError(f"OPENTRIP_LOCAL_STATE_NOT_FOUND: {exc}") from exc
    return read_state(leveldb_path, STATE_KEY)


def _store_mtime(controller: Any, directory: str, timeout: int) -> float:
    """Return the newest file modification time in a LevelDB directory (0 when absent)."""
    program = (
        "import json, os\n"
        "newest = 0.0\n"
        "try:\n"
        "    for name in os.listdir(%s):\n"
        "        newest = max(newest, os.path.getmtime(os.path.join(%s, name)))\n"
        "except OSError:\n"
        "    pass\n"
        "print(json.dumps(newest))\n"
    ) % (json.dumps(directory), json.dumps(directory))
    if controller is not None and hasattr(controller, "run_python_script"):
        try:
            raw = controller.run_python_script(program, timeout=timeout)
            return float(str(raw.get("stdout") or raw.get("output") or "0").strip().splitlines()[-1])
        except Exception:  # noqa: BLE001 - recency is only a tie-breaker
            return 0.0
    try:
        local = os.path.expandvars(os.path.expanduser(directory))
        return max((os.path.getmtime(os.path.join(local, name)) for name in os.listdir(local)), default=0.0)
    except OSError:
        return 0.0


def read_opentrip_local_state(
    controller: Any = None,
    *,
    timeout: int = 20,
    leveldb_path: str = DEFAULT_LEVELDB_PATH,
) -> dict[str, Any]:
    """Return the stored OpenTrip document, or raise when none is stored.

    The declared store and the desktop launcher's profile are both read; when
    both hold a document, the most recently written store wins.
    """
    declared = str(leveldb_path)
    candidates = [declared]
    if LAUNCHER_LEVELDB_PATH not in candidates:
        candidates.append(LAUNCHER_LEVELDB_PATH)
    if controller is None:
        candidates = [path for path in candidates if os.path.isdir(os.path.expandvars(os.path.expanduser(path)))]
        if not candidates:
            raise RuntimeError("OPENTRIP_LEVELDB_NOT_FOUND: %s" % declared)
    found = []
    for candidate in candidates:
        try:
            document = _read_document(controller, candidate, timeout)
        except RuntimeError:
            continue
        if isinstance(document, Mapping) and document:
            found.append((_store_mtime(controller, candidate, timeout), len(found), candidate, document))
    if not found:
        raise RuntimeError("OPENTRIP_LOCAL_STATE_NOT_FOUND: %s" % ", ".join(candidates))
    _, _, directory, document = max(found, key=lambda row: (row[0], -row[1]))
    return {
        "state": dict(document),
        "source_file": directory,
        "selection_rule": "newest stored document for the OpenTrip origin",
    }


def _seed_object(text: str) -> dict[str, Any]:
    marker = text.find("opentripSeed")
    start = text.find("{", marker)
    if marker < 0 or start < 0:
        raise RuntimeError("OPENTRIP_SEED_NOT_FOUND: no seed object in the data file")
    depth = 0
    for index in range(start, len(text)):
        char = text[index]
        if char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                return dict(json.loads(text[start:index + 1]))
    raise RuntimeError("OPENTRIP_SEED_NOT_FOUND: unterminated seed object")


def read_opentrip_seed_baseline(
    controller: Any = None,
    *,
    timeout: int = 20,
    seed_data_path: str = DEFAULT_SEED_DATA_PATH,
) -> dict[str, Any]:
    """Return the bookings and account OpenTrip shows before anything is stored."""
    path = Path(os.path.expandvars(os.path.expanduser(seed_data_path)))
    if controller is not None and hasattr(controller, "run_python_script"):
        # The seed file lives in the guest, not on the host running the evaluator.
        script = (
            "import sys\n"
            "sys.stdout.write(open(%s, encoding='utf-8', errors='replace').read())\n"
            % json.dumps(seed_data_path)
        )
        raw = controller.run_python_script(script, timeout=timeout)
        text = str(raw.get("stdout") or raw.get("output") or "")
        if not text.strip():
            raise RuntimeError("OPENTRIP_SEED_NOT_FOUND: %s" % seed_data_path)
    elif path.is_file():
        text = path.read_text(encoding="utf-8", errors="replace")
    else:
        raise RuntimeError("OPENTRIP_SEED_NOT_FOUND: %s" % seed_data_path)
    seed = _seed_object(text)
    account = seed.get("benchmarkAccount") if isinstance(seed.get("benchmarkAccount"), Mapping) else {}
    phone = re.sub(r"\D", "", str(account.get("phone") or ""))
    session = {
        "loggedIn": bool(account),
        "user": {
            "name": account.get("name"),
            "phone": phone or account.get("phone"),
            "id": account.get("id"),
        },
    }
    return {
        "state": {
            "session": session,
            "accounts": seed.get("accounts") or [],
            "travelers": seed.get("travelers") or [],
            "bookings": seed.get("defaultBookings") or [],
        },
        "source_file": str(path),
        "selection_rule": "shipped seed data shown before the store is written",
    }
